package es.hugoalvarezajenjo.sproutstudio.core.buildinfo

import java.util.Properties

/** Facts about this build, read from `sproutstudio/build-info.properties` (generated by Gradle). */
object BuildInfo {
    /** The app version, e.g. "1.1.0"; "dev" if the resource is missing (an IDE run without Gradle). */
    val version: String by lazy {
        BuildInfo::class.java.getResourceAsStream("/sproutstudio/build-info.properties")
            ?.use { Properties().apply { load(it) }.getProperty("version") }
            ?: "dev"
    }
}
